3	import * as React from "react";
4	import { useTransition } from "react";
5	import Link from "next/link";
6	import { Phone, CalendarClock, X, Check } from "lucide-react";
7	import { Card } from "@/components/ui/Card";
8	import { Button } from "@/components/ui/Button";
9	import { Field, Input } from "@/components/ui/Field";
10	import { StatusBadge } from "@/components/ui/StatusBadge";
11	import { cancelBooking, rescheduleBooking } from "@/app/(customer)/account/actions";
12	import { t } from "@/lib/i18n";
13	import { useToast } from "@/components/ui/Toast";
14	
15	export interface UpcomingItem {
16	  id: string;
17	  providerName: string;
18	  blockMinutes: number;
19	  status: "confirmed" | "in_progress";
20	  whenLabel: string;
21	}
22	
23	export function UpcomingBookings({ items }: { items: UpcomingItem[] }) {
24	  const [pending, startTransition] = useTransition();
25	  const [rescheduleId, setRescheduleId] = React.useState<string | null>(null);
26	  const [confirmId, setConfirmId] = React.useState<string | null>(null);
27	  const [newTime, setNewTime] = React.useState("");
28	  const { announce, toast } = useToast();
29	
30	  function cancel(id: string) {
31	    setConfirmId(null);
32	    startTransition(async () => {
33	      const res = await cancelBooking(id);
34	      if (!res.ok) {
35	        toast(res.error ?? t("booking.error"), "alert");
36	        return;
37	      }
38	      announce(
39	        res.released ? t("account.cancelledRefund") : t("account.cancelledCharged"),
40	        true,
41	      );
42	    });
43	  }
44	
45	  function saveReschedule(id: string) {
46	    if (!newTime) return;
47	    startTransition(async () => {
48	      const res = await rescheduleBooking({
49	        bookingId: id,
50	        scheduledAt: new Date(newTime).toISOString(),
51	      });
52	      if (!res.ok) {
53	        toast(res.error ?? t("booking.error"), "alert");
54	        return;
55	      }
56	      setRescheduleId(null);
57	      setNewTime("");
58	      announce(t("account.rescheduled"), true);
59	    });
60	  }
61	
62	  if (items.length === 0) {
63	    return (
64	      <Card>
65	        <p className="text-base text-ink-soft">{t("account.upcomingNone")}</p>
66	      </Card>
67	    );
68	  }
69	
70	  return (
71	    <ul className="flex flex-col gap-3">
72	      {items.map((item) => (
73	        <Card as="li" key={item.id} className="flex flex-col gap-3">
74	          <div className="flex flex-wrap items-center justify-between gap-3">
75	            <div className="flex items-center gap-3">
76	              <StatusBadge tone="info" icon={CalendarClock}>
77	                {item.whenLabel}
78	              </StatusBadge>
79	              <span className="text-base font-bold text-ink">
80	                {t("account.bookingSummary", {
81	                  name: item.providerName,
82	                  minutes: item.blockMinutes,
83	                })}
84	              </span>
85	            </div>
86	            <div className="flex flex-wrap items-center gap-2">
87	              <Link href={`/session/${item.id}`} className="rounded-btn">
88	                <Button icon={Phone}>{t("account.join")}</Button>
89	              </Link>
90	              {/* Reschedule/Cancel only apply to a not-yet-started booking. */}
91	              {item.status === "confirmed" ? (
92	                <>
93	                  <Button
94	                    variant="ghost"
95	                    icon={CalendarClock}
96	                    onClick={() => {
97	                      setConfirmId(null);
98	                      setRescheduleId(rescheduleId === item.id ? null : item.id);
99	                    }}
100	                  >
101	                    {t("account.reschedule")}
102	                  </Button>
103	                  <Button
104	                    variant="ghost"
105	                    icon={X}
106	                    onClick={() => {
107	                      setRescheduleId(null);
108	                      setConfirmId(item.id);
109	                    }}
110	                    disabled={pending}
111	                  >
112	                    {t("account.cancel")}
113	                  </Button>
114	                </>
115	              ) : null}
116	            </div>
117	          </div>
118	
119	          {confirmId === item.id ? (
120	            <div
121	              role="group"
122	              aria-label={t("account.cancelConfirm")}
123	              className="flex flex-wrap items-center gap-3 border-t border-border pt-3"
124	            >
125	              <span className="text-base font-bold text-ink">
126	                {t("account.cancelConfirm")}
127	              </span>
128	              <Button
129	                variant="danger"
130	                icon={X}
131	                onClick={() => cancel(item.id)}
132	                disabled={pending}
133	              >
134	                {t("account.confirmCancel")}
135	              </Button>
136	              <Button variant="ghost" onClick={() => setConfirmId(null)}>
137	                {t("account.keepBooking")}
138	              </Button>
139	            </div>
140	          ) : null}
141	
142	          {rescheduleId === item.id ? (
143	            <div className="flex flex-wrap items-end gap-3 border-t border-border pt-3">
144	              <Field label={t("account.rescheduleHeading")}>
145	                {(p) => (
146	                  <Input
147	                    {...p}
148	                    type="datetime-local"
149	                    value={newTime}
150	                    onChange={(e) => setNewTime(e.target.value)}
151	                  />
152	                )}
153	              </Field>
154	              <Button
155	                icon={Check}
156	                onClick={() => saveReschedule(item.id)}
157	                disabled={pending || !newTime}
158	              >
159	                {t("account.rescheduleSave")}
160	              </Button>
161	            </div>
162	          ) : null}
163	        </Card>
164	      ))}
165	    </ul>
166	  );
167	}
