53	            </Link>
54	          ) : null}
55	          <a
56	            href={`/account/receipt/${r.bookingId}`}
57	            aria-label={t("account.receiptFor", {
58	              name: r.listenerName,
59	              date: r.dateLabel,
60	            })}
61	            className="font-bold text-primary underline underline-offset-[3px]"
62	          >
63	            {t("account.seeReceipt")}
64	          </a>
65	        </span>
66	      ),
67	    },
68	  ];
69	
70	  return (
71	    <DataTable
72	      caption={t("account.pastCaption")}
73	      columns={columns}
74	      rows={rows}
75	      getRowKey={(r) => r.id}
76	      emptyText={t("account.pastNone")}
77	    />
78	  );
79	}
